semantic = {
    id_
    for id_, record in doc.records.items()
    if record.kind not in ("EPTJNV" if doc.format == 2 else "EPTJN")
}
proof_edges = {
    id_: targets & semantic for id_, targets in adjacency.items() if id_ in semantic
}
scope_cache = {}

def scope(id_):
    if id_ not in scope_cache:
        scope_cache[id_] = closure(proof_edges, [id_]) if id_ in semantic else set()
    return scope_cache[id_]

def bound(evidence, passing=False):
    result = set()
    for reference in evidence:
        proof = doc.records[reference.id]
        if proof.fields.get("ob", False):
            continue
        if not passing or proof.fields["rs"].value == "pass":
            result.update(refs(proof.fields["bs"]))
    return result

for id_, record in doc.records.items():
    f = record.fields
    if record.kind == "D":
        for key in ("wt", "wr", "wy", "rs", "pc"):
            _require(
                bool(f[key])
                and (not isinstance(f[key], str) or bool(f[key].strip())),
                "decision_evidence",
                f"{id_}.{key} is empty",
            )
        _require(
            scope(id_) <= bound(f["pc"]),
            "decision_proof",
            f"{id_}: proof must bind the decision, sources and semantic targets",
        )
    if record.kind == "K":
        for key in ("ap", "op", "ck", "so"):
            _require(bool(f[key]), "knowledge", f"{id_}.{key} is empty")
        if f.get("pc"):
            _require(
                scope(id_) <= bound(f["pc"]),
                "method_poc",
                f"{id_}: proof must bind this method and its sources",
            )
    if record.kind == "R":
        _require(bool(f["so"]) and bool(f["vr"]), "runtime_source", id_)
    if record.kind == "C":
        _require(
            len(f["px"]) == 2 and all(0 < n <= 65536 for n in f["px"]),
            "dimensions",
            id_,
        )
        _require(
            all(
                re.fullmatch(r"#[0-9A-Fa-f]{6}(?:[0-9A-Fa-f]{2})?", c)
                for c in f["pl"]
            ),
            "palette",
            id_,
        )
    if record.kind == "S":
        _require(
            len(f["ln"]) in {0, 2}
            and (not f["ln"] or 1 <= f["ln"][0] <= f["ln"][1]),
            "source_range",
            id_,
        )
        _require(bool(f["ur"]), "source_uri", id_)
    if record.kind in ("S", "E"):
        try:
            datetime.fromisoformat(f["at"])
        except ValueError as error:
            raise PixlError("date", id_) from error
    if record.kind == "E":
        _require(
            isinstance(f["bs"], list) and bool(f["bs"]), "evidence_binding", id_
        )
        targets = set()
        for binding in f["bs"]:
            _require(
                isinstance(binding, dict) and set(binding) == {"rf", "dg"},
                "evidence_binding",
                id_,
            )
            _require(
                _type(binding["rf"], "ref:*", doc)
                and _type(binding["dg"], "sha", doc),
                "evidence_binding",
                id_,
            )
            target = binding["rf"].id
            _require(
                target not in targets and doc.records[target].kind != "E",
                "evidence_binding",
                f"{id_}: duplicate or recursive proof",
            )
            targets.add(target)
            if not f.get("ob", False):
                _require(
                    record_hash(doc.records[target]) == binding["dg"],
                    "stale_evidence",
                    f"{id_} binds outdated {target}",
                )
        for target in targets:
            if doc.records[target].kind == "X" and not f.get("ob", False):
                dependencies = scope(target)
                _require(
                    dependencies <= targets,
                    "evidence_context",
                    f"{id_}: bind artifact {target} and its full contract/reference closure",
                )
    if record.kind == "T" and doc.format == 1:
        _require(bool(f["dc"]), "task_decision", id_)
        if f["st"].value in ("active", "done"):
            for method in f["kn"]:
                proofs = doc.records[method.id].fields.get("pc", [])
                _require(
                    scope(method.id) <= bound(proofs, passing=True),
                    "method_poc",
                    method.id,
                )
        if f["st"].value == "done":
            _require(
                bool(f["io"])
                and all(
                    doc.records[d.id].fields["st"].value == "done" for d in f["dp"]
                ),
                "completion",
                f"{id_}: artifacts/prerequisites",
            )
            passing = [
                doc.records[e.id]
                for e in f["ev"]
                if doc.records[e.id].fields["rs"].value == "pass"
                and not doc.records[e.id].fields.get("ob", False)
            ]
            needed = set(refs(f["io"]))
            covered = (
                set().union(*(set(refs(e.fields["bs"])) for e in passing))
                if passing
                else set()
            )
            _require(
                needed <= covered,
                "completion",
                f"{id_}: evidence must bind all artifacts",
            )
    if record.kind == "J":
        if f["si"].value in ("submitted", "running", "succeeded"):
            _require(bool(f["ri"]), "job_identity", id_)
        if f["si"].value == "succeeded":
            _require(bool(f["ev"]), "job_evidence", id_)
    if record.kind == "N":
        _require(0 <= f["rv"] <= doc.revision, "handoff_revision", id_)
    if root is not None and record.kind in ("S", "X", "E"):

                    "verdict_proof", f"{id_}: receipts must bind the exact candidate, criterion and their semantic scopes",
                )

    for id_, record in doc.records.items():
        if record.kind != "T":
            continue
        f = record.fields
        _unique(f["op"], "output_owner", f"{id_}.op repeats a planned output")
        _unique(f["vr"], "verdict_owner", f"{id_}.vr repeats a verdict")
        for reference in f["op"]:
            _require(
                doc.records[reference.id].fields["tk"].id == id_,
                "output_owner", f"{id_}: {reference.id} belongs to another task",
            )
        for reference in f["vr"]:
            _require(
                doc.records[reference.id].fields["tk"].id == id_,
                "verdict_owner", f"{id_}: {reference.id} belongs to another task",
            )
        for choice_id in _output_choices(doc, f):
            _require(
                doc.records[choice_id].fields["pr"] == f["pr"],
                "task_project", f"{id_}: output choice {choice_id} belongs to another project",
            )
        nominees = {}
        for reference in f["ca"]:
            candidate = doc.records[reference.id].fields
            output = candidate.get("of")
            _require(
                output is not None and output.id in _ids(f["op"]),
                "candidate_output", f"{id_}: nominated {reference.id} must belong to a planned output",
            )
            _require(
                output.id not in nominees, "candidate_nomination",
                f"{id_}: only one candidate may be nominated for {output.id}",
            )
            nominees[output.id] = reference.id
        if f["st"].value in {"active", "done"}:
            reasons = _activation_blockers(doc, id_, scope, bound)
            if reasons:
                code, detail = reasons[0].split(": ", 1)
                raise PixlError(code, detail)
        if f["st"].value == "done":
            _require(
                bool(f["op"]) and set(nominees) == _ids(f["op"]),
                "completion", f"{id_}: every planned output needs one nominated candidate",
            )
            for output_id, candidate_id in nominees.items():
                for requirement in doc.records[output_id].fields["rq"]:
                    verdict = current_verdicts.get((id_, candidate_id, requirement.id))
                    status = verdict.fields["st"].value if verdict is not None else "unperformed"
                    _require(
                        status == "pass", "completion",
                        f"{id_}: {candidate_id} requirement {requirement.id} is {status}",
                    )
    return doc


def blockers(doc, task_id):
    """Return activation blockers for a task in an otherwise valid PX2 graph."""
    from .graph import proof_scope

    _require(task_id in doc.records and doc.records[task_id].kind == "T", "unknown_task", task_id)

    def bound(evidence, passing=False):
        covered = set()
        for reference in evidence:
            receipt = doc.records[reference.id].fields
            if not receipt.get("ob", False) and (not passing or receipt["rs"].value == "pass"):
                covered.update(binding["rf"].id for binding in receipt["bs"])
        return covered

    return _activation_blockers(doc, task_id, lambda id_: proof_scope(doc, [id_]), bound)


def report(doc):
    """Describe an already validated PX2 graph without changing its state.

    Requirements are shown for each current nominee and for retained older
    candidates. An absent current verdict is unperformed, never a pass.
    """
    intake, tasks, ready = [], [], []
    current = {
        (r.fields["tk"].id, r.fields["xr"].id, r.fields["rq"].id): r
        for r in doc.records.values() if r.kind == "V" and not r.fields.get("ob", False)
    }
    candidates = {}
    for id_, record in sorted(doc.records.items()):
        if record.kind == "X" and "of" in record.fields:
            candidates.setdefault(record.fields["of"].id, []).append(id_)

    def requirements(task_id, output, candidate_id):
        results = []
        for reference in output["rq"]:
            criterion = doc.records[reference.id].fields
            verdict = current.get((task_id, candidate_id, reference.id))
            results.append({
                "id": reference.id, "name": criterion["nm"],
                "check": criterion["ck"],
                "domain": criterion["dm"].value, "mode": criterion["md"].value,
                "status": verdict.fields["st"].value if verdict is not None else "unperformed",
                "verdict": verdict.id if verdict is not None else None,
                "reason": verdict.fields["wy"] if verdict is not None else None,
                "reviewer": verdict.fields["wh"].id if verdict is not None else None,
                "evidence": [e.id for e in verdict.fields["ev"]] if verdict is not None else [],
            })
        return results

    for id_, record in sorted(doc.records.items()):
        f = record.fields
        if record.kind == "I":
            intake.append({
                "id": id_, "project": f["pr"].id, "key": f["ky"],
                "status": f["st"].value, "value": to_data(f["vl"]),
                "sources": [s.id for s in f["so"]], "rationale": f["wy"],
            })
        elif record.kind == "T":
            reasons = blockers(doc, id_)
            if f["st"].value == "open" and not reasons:
                ready.append(id_)

        if doc.revision != 0:
            raise PixlError("revision", "initial state must be revision 0")
        validate(doc, root if root is not None else folder.parent)
        _acceptance_plan(None, doc)
        from . import delivery, jobs

        jobs.transitions(None, doc, root if root is not None else folder.parent, folder)
        delivery.transitions(None, doc, root if root is not None else folder.parent, folder)
        return _publish(folder, doc)


def load(folder):
    path = Path(folder) / "state.px"
    try:
        return parse(path.read_bytes())
    except OSError as error:
        raise PixlError("store_read", str(path)) from error


def _acceptance_plan(current, candidate):
    """Require a saved, unchanged acceptance plan before recording evaluation.

    Called only after full candidate validation, so traversal cannot dereference
    malformed candidate references. This checks recorded order, not human honesty.
    """
    if candidate.format != 2:
        return
    for id_, record in candidate.records.items():
        if record.kind != "V":
            continue
        if current is not None and id_ in current.records:
            continue
        if record.fields.get("ob", False):
            raise PixlError(
                "verdict_history",
                f"{id_}: a new verdict must be validated before later supersession",
            )
        if record.fields["st"].value == "unavailable":
            continue
        artifact = candidate.records[record.fields["xr"].id]
        output = artifact.fields["of"].id
        if current is None or output not in current.records:
            raise PixlError(
                "acceptance_plan",
                f"{id_}: save the output and criteria before recording evaluation",
            )
        planned = proof_scope(candidate, [output])
        if planned != proof_scope(current, [output]) or any(
            candidate.records[target] != current.records.get(target)
            for target in planned
        ):
            raise PixlError(
                "acceptance_plan",
                f"{id_}: acceptance plan changed; save it before new evaluation",
            )


